<script setup>
import {computed,onMounted,reactive,ref} from 'vue';import {useRoute,useRouter} from 'vue-router';import {ElMessage,ElMessageBox} from 'element-plus';import api,{messageOf} from '../../api/request.js';import CourseNotices from './CourseNotices.vue';import CourseMaterials from './CourseMaterials.vue';import {useDraggableTabs} from '../../composables/useDraggableTabs.js';
const route=useRoute(),router=useRouter(),course=ref({}),students=ref([]),assignments=ref([]),tab=ref('assignments'),studentDialog=ref(false),assignmentDialog=ref(false),editId=ref(null),studentForm=reactive({username:'',name:''}),aform=reactive({title:'',description:'',type:'document',deadline:'',total_score:100,allow_resubmit_count:1,submission_mode:'overwrite',max_file_mb:200});
const tabsRoot=ref(null),tabDefs=ref([{label:'作业管理',name:'assignments'},{label:'通知',name:'notices'},{label:'学习资料',name:'materials'},{label:'学生名单',name:'students'}]);
useDraggableTabs(tabsRoot,tabDefs,'teacher-course');
const published=computed(()=>assignments.value.filter(a=>a.status==='published').length);
async function load(){try{const [c,s,a]=await Promise.all([api.get(`/courses/${route.params.id}`),api.get(`/courses/${route.params.id}/students`),api.get(`/courses/${route.params.id}/assignments`)]);course.value=c.data;students.value=s.data;assignments.value=a.data}catch(e){ElMessage.error(messageOf(e))}}
async function addStudent(){try{await api.post(`/courses/${route.params.id}/students`,studentForm);studentDialog.value=false;Object.assign(studentForm,{username:'',name:''});ElMessage.success('学生已加入');load()}catch(e){ElMessage.error(messageOf(e))}}
async function importFile(options){const fd=new FormData();fd.append('file',options.file);try{const {data}=await api.post(`/courses/${route.params.id}/students/import`,fd);ElMessage.success(`新增账号${data.created}人，加入课程${data.joined}人，重复${data.duplicated}人`);options.onSuccess();load()}catch(e){options.onError(e);ElMessage.error(messageOf(e))}}
async function studentAction(s,action){try{if(action==='remove'){await ElMessageBox.confirm(`将${s.name}移出课程？`,'确认');await api.delete(`/courses/${route.params.id}/students/${s.id}`)}else if(action==='reset'){await api.post(`/students/${s.id}/reset-password`);ElMessage.success('密码已重置为123456')}else await api.put(`/students/${s.id}/status`,{status:s.status==='active'?'disabled':'active'});load()}catch(e){if(e!=='cancel')ElMessage.error(messageOf(e))}}
function openAssignment(a){editId.value=a?.id||null;Object.assign(aform,a?{title:a.title,description:a.description,type:a.type,deadline:a.deadline,total_score:a.total_score,allow_resubmit_count:a.allow_resubmit_count,submission_mode:a.submission_mode||'overwrite',max_file_mb:a.max_file_mb||200}:{title:'',description:'',type:'document',deadline:'',total_score:100,allow_resubmit_count:1,submission_mode:'overwrite',max_file_mb:200});assignmentDialog.value=true}
async function saveAssignment(){try{editId.value?await api.put(`/assignments/${editId.value}`,aform):await api.post(`/courses/${route.params.id}/assignments`,aform);assignmentDialog.value=false;ElMessage.success('作业已保存');load()}catch(e){ElMessage.error(messageOf(e))}}
async function assignmentAction(a,action){try{if(action==='delete'){await ElMessageBox.confirm('确认删除这项作业？','确认',{type:'warning'});await api.delete(`/assignments/${a.id}`)}else await api.post(`/assignments/${a.id}/${action}`);ElMessage.success(action==='publish'?'作业已发布':'作业已关闭');load()}catch(e){if(e!=='cancel')ElMessage.error(messageOf(e))}}
onMounted(load);
</script>
<template><div><div class="page-head"><div><el-button text @click="router.push('/teacher/courses')">← 返回课程</el-button><h1>{{course.name||'课程详情'}}</h1><p>{{course.code}} · 邀请码 <b>{{course.invite_code}}</b></p></div><div><el-button @click="studentDialog=true">添加学生</el-button><el-button type="primary" color="#15554e" @click="openAssignment()">发布新作业</el-button></div></div><div class="stat-strip"><div class="stat"><b>{{students.length}}</b><span>课程学生</span></div><div class="stat"><b>{{assignments.length}}</b><span>全部作业</span></div><div class="stat"><b>{{published}}</b><span>进行中</span></div><div class="stat"><b>{{course.invite_code||'—'}}</b><span>课程邀请码</span></div></div><div ref="tabsRoot"><el-tabs v-model="tab" class="section-tabs"><el-tab-pane v-for="def in tabDefs" :key="def.name" :label="def.label" :name="def.name"/></el-tabs></div><div v-if="tab==='assignments'" class="panel"><div v-if="assignments.length"><article v-for="a in assignments" :key="a.id" class="assignment-card"><div style="display:flex;justify-content:space-between;gap:20px"><div><span class="badge">{{({draft:'草稿',published:'已发布',closed:'已关闭'})[a.status]}}</span><h3>{{a.title}}</h3><p>{{a.description||'暂无作业说明'}}</p><span class="hint">截止：{{a.deadline||'不限'}} · 满分{{a.total_score}} · 可重交{{a.allow_resubmit_count===-1?'不限':a.allow_resubmit_count+'次'}} · {{a.submission_mode==='append'?'追加模式':'覆盖模式'}}<template v-if="a.type!=='online'"> · 单文件≤{{a.max_file_mb>=1024?'1G':a.max_file_mb+'M'}}</template></span></div><div class="assignment-actions"><el-button @click="openAssignment(a)">编辑</el-button><el-button v-if="a.status==='draft'" type="success" @click="assignmentAction(a,'publish')">发布</el-button><el-button v-if="a.status==='published'" type="warning" @click="assignmentAction(a,'close')">关闭</el-button><el-button v-if="a.status==='closed'" type="success" @click="assignmentAction(a,'publish')">重新发布</el-button><el-button type="primary" color="#15554e" @click="router.push(`/teacher/assignments/${a.id}`)">查看提交</el-button><el-button type="danger" text @click="assignmentAction(a,'delete')">删除</el-button></div></div></article></div><div v-else class="empty">还没有作业，创建后可发布给学生。</div></div><div v-else-if="tab==='notices'" class="panel"><CourseNotices :course-id="route.params.id" /></div><div v-else-if="tab==='materials'" class="panel"><CourseMaterials :course-id="route.params.id" /></div><div v-else class="panel"><div class="toolbar"><el-button @click="studentDialog=true">手动添加</el-button><el-upload :show-file-list="false" accept=".xlsx,.xls" :http-request="importFile"><el-button type="primary" plain>导入Excel名单</el-button></el-upload><span class="hint">A列学号，B列姓名，首行为表头</span></div><el-table :data="students" stripe><el-table-column prop="username" label="学号"/><el-table-column prop="name" label="姓名"/><el-table-column prop="submission_count" label="已交作业"/><el-table-column label="状态"><template #default="{row}"><el-tag :type="row.status==='active'?'success':'info'">{{row.status==='active'?'正常':'停用'}}</el-tag></template></el-table-column><el-table-column label="操作" width="250"><template #default="{row}"><el-button link @click="studentAction(row,'reset')">重置密码</el-button><el-button link @click="studentAction(row,'status')">{{row.status==='active'?'停用':'启用'}}</el-button><el-button link type="danger" @click="studentAction(row,'remove')">移除</el-button></template></el-table-column></el-table></div><el-dialog v-model="studentDialog" title="添加学生" width="min(460px,92vw)"><el-form label-position="top"><el-form-item label="学号"><el-input v-model="studentForm.username"/></el-form-item><el-form-item label="姓名"><el-input v-model="studentForm.name"/></el-form-item></el-form><template #footer><el-button @click="studentDialog=false">取消</el-button><el-button type="primary" color="#15554e" @click="addStudent">添加</el-button></template></el-dialog><el-dialog v-model="assignmentDialog" :title="editId?'编辑作业':'创建作业'" width="min(620px,94vw)"><el-form label-position="top"><el-form-item label="作业标题"><el-input v-model="aform.title"/></el-form-item><el-form-item label="作业要求"><el-input v-model="aform.description" type="textarea" :rows="4"/></el-form-item><div style="display:grid;grid-template-columns:1fr 1fr;gap:12px"><el-form-item label="类型"><el-select v-model="aform.type" style="width:100%"><el-option label="文档/文件" value="document"/><el-option label="图片" value="image"/><el-option label="视频" value="video"/><el-option label="在线作答" value="online"/></el-select></el-form-item><el-form-item label="截止时间"><el-date-picker v-model="aform.deadline" type="datetime" value-format="YYYY-MM-DD HH:mm:ss" style="width:100%"/></el-form-item><el-form-item label="满分"><el-input-number v-model="aform.total_score" :min="1"/></el-form-item><el-form-item label="允许重交次数（-1不限）"><el-input-number v-model="aform.allow_resubmit_count" :min="-1"/></el-form-item></div><el-form-item label="提交模式"><el-radio-group v-model="aform.submission_mode"><el-radio value="overwrite">覆盖模式（重新提交会替换原文件）</el-radio><el-radio value="append">追加模式（重新提交作为补充，下载时统一打包）</el-radio></el-radio-group></el-form-item><el-form-item v-if="aform.type!=='online'" label="文件大小上限"><el-radio-group v-model="aform.max_file_mb"><el-radio :value="100">100M</el-radio><el-radio :value="200">200M</el-radio><el-radio :value="500">500M</el-radio><el-radio :value="1024">1G</el-radio></el-radio-group><span class="hint" style="margin-left:12px">学生上传的单文件不能超过该大小</span></el-form-item></el-form><template #footer><el-button @click="assignmentDialog=false">取消</el-button><el-button type="primary" color="#15554e" @click="saveAssignment">保存</el-button></template></el-dialog></div></template>
